args.sparql:
SELECT ?person ?birth ?label WHERE {
  VALUES ?person { dbr:Amir_Temraz dbr:Sophie_Ingle }
  ?person dbo:birthDate ?birth .
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = 'en') }
}

SELECT DISTINCT ?younger ?youngerLabel ?youngerBirth WHERE {
  dbr:Amir_Temraz dbo:birthDate ?bdA .
  dbr:Sophie_Ingle dbo:birthDate ?bdB .
  {
    FILTER(?bdA > ?bdB)
    BIND(dbr:Amir_Temraz AS ?younger)
    BIND(?bdA AS ?youngerBirth)
  }
  UNION
  {
    FILTER(?bdB > ?bdA)
    BIND(dbr:Sophie_Ingle AS ?younger)
    BIND(?bdB AS ?youngerBirth)
  }
  OPTIONAL { ?younger rdfs:label ?youngerLabel . FILTER(lang(?youngerLabel) = 'en') }
}

SELECT ?younger ?youngerLabel ?youngerBirth WHERE {
  VALUES (?p1 ?p2) {(dbr:Amir_Temraz dbr:Sophie_Ingle)}
  ?p1 dbo:birthDate ?bd1 .
  ?p2 dbo:birthDate ?bd2 .
  FILTER(?bd2 > ?bd1)
  BIND(?p2 AS ?younger)
  BIND(?bd2 AS ?youngerBirth)
  OPTIONAL { ?younger rdfs:label ?youngerLabel . FILTER(lang(?youngerLabel) = 'en') }
}

